arguments.command:
set -e
cat > /etc/nginx/sites-available/default <<'EOF'
server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate     /etc/nginx/ssl/self.crt;
    ssl_certificate_key /etc/nginx/ssl/self.key;

    location /dev/ {
        alias /var/www/dev/;
        index index.html;
    }

    location / {
        root /var/www/main;
        index index.html;
    }
}
EOF
nginx -t
echo "== ok =="

